exemplu_cod:
note = [8, 9, 10, 6, 7]

for nota in note:
    if nota >= 9:
        print(nota, "- notă foarte bună")
    else:
        print(nota)

exercitiu_interactiv.solutie:
note = [8, 6, 10, 5, 7]

for nota in note:
    if nota < 7:
        print(nota)

def cel_mai_mare(a, b):
    if a > b:
        return a
    return b

rezultat = cel_mai_mare(3, 9)
print("Cel mai mare este:", rezultat)
